await page.goto(baseUrl, { waitUntil: 'domcontentloaded' })
const uniReady = await page.waitForFunction(() => typeof window.uni?.setStorageSync === 'function', null, { timeout: 15000 }).then(() => true).catch(() => false)
if (!uniReady) {
  const diagnostic = await page.evaluate(() => ({
    url: location.href,
    title: document.title,
    readyState: document.readyState,
    bodyText: document.body?.innerText?.slice(0, 180),
    scriptUrls: [...document.scripts].map(script => script.src).filter(Boolean),
    uniType: typeof window.uni,
    windowKeys: Object.keys(window).filter(key => /uni/i.test(key)).slice(0, 20),
    storageKeys: Object.keys(localStorage),
  }))
  throw new Error(`H5 runtime did not initialize uni storage: ${JSON.stringify({ diagnostic, pageErrors, consoleErrors, requestFailures })}`)
}
const storageReady = await page.evaluate(() => {
  if (typeof window.uni?.setStorageSync !== 'function') return false
  window.uni.setStorageSync('flood-token-v1', 'visual-only-token')
  window.uni.setStorageSync('flood-login-user-v1', JSON.stringify({ userId: 'visual-user', userName: 'visual-only', nickName: '截图校验' }))
  window.uni.reLaunch({ url: '/pages/home/index' })
  return window.uni.getStorageSync('flood-token-v1') === 'visual-only-token'
})

tool_input.new_string:
await page.goto(baseUrl, { waitUntil: 'domcontentloaded' })
await page.waitForFunction(() => typeof window.uni === 'object', null, { timeout: 15000 })
const storageReady = await page.evaluate(() => {
  const api = window.uni
  if (!api || typeof api !== 'object') return false
  try {
    if (typeof api.getStorageSync !== 'function') api.getStorageSync = key => localStorage.getItem(key) ?? ''
    if (typeof api.setStorageSync !== 'function') api.setStorageSync = (key, value) => localStorage.setItem(key, String(value))
    if (typeof api.removeStorageSync !== 'function') api.removeStorageSync = key => localStorage.removeItem(key)
    api.setStorageSync('flood-token-v1', 'visual-only-token')
    api.setStorageSync('flood-login-user-v1', JSON.stringify({ userId: 'visual-user', userName: 'visual-only', nickName: '截图校验' }))
    if (typeof api.reLaunch === 'function') api.reLaunch({ url: '/pages/home/index' })
    else location.hash = '/pages/home/index'
    return api.getStorageSync('flood-token-v1') === 'visual-only-token'
  } catch {
    return false
  }
})
